from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2]


def read(path):
    return (ROOT / path).read_text(encoding="utf-8")


def write(path, text):
    (ROOT / path).write_text(text, encoding="utf-8", newline="\n")


def replace_once(path, old, new):
    text = read(path)
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{path}: expected one literal match, got {count}: {old[:100]!r}")
    write(path, text.replace(old, new, 1))


def regex_once(path, pattern, replacement, flags=re.S):
    text = read(path)
    new, count = re.subn(pattern, replacement, text, count=1, flags=flags)
    if count != 1:
        raise RuntimeError(f"{path}: expected one regex match, got {count}: {pattern[:100]!r}")
    write(path, new)


# Inventory: Pair must consume the two loaded launchers belonging to the same authored paired hatch group.
regex_once(
    "Game/Weapons/P700LauncherInventory.h",
    r'''    \[\[nodiscard\]\] std::expected<std::vector<std::size_t>, std::string> LoadedSlotIndices\(\n        const std::size_t requestedCount\) const\n    \{.*?\n    \}\n\n    // Consumption is explicit''',
    '''    [[nodiscard]] std::expected<std::vector<std::size_t>, std::string> LoadedSlotIndices(\n        const std::size_t requestedCount) const\n    {\n        if (requestedCount == 0U || requestedCount > AnteyP700LauncherSlotCount)\n        {\n            return std::unexpected("P-700 salvo requested an invalid launcher count");\n        }\n        if (requestedCount == 1U)\n        {\n            const auto first = FirstLoadedSlotIndex();\n            if (!first)\n                return std::unexpected("P-700 launcher inventory is exhausted");\n            return std::vector<std::size_t>{*first};\n        }\n        if (requestedCount == 2U)\n        {\n            // The production Antey contract is 24 missiles under 12 paired hatch groups. A Pair salvo uses\n            // the two still-loaded anchors under one real authored hatch instead of inventing another lid.\n            for (std::size_t first = 0U; first < slots_.size(); ++first)\n            {\n                if (slots_[first].state != P700LauncherSlotState::Loaded ||\n                    slots_[first].anchor.hatchGroupSemanticId.empty())\n                    continue;\n                for (std::size_t second = first + 1U; second < slots_.size(); ++second)\n                {\n                    if (slots_[second].state == P700LauncherSlotState::Loaded &&\n                        slots_[second].anchor.hatchGroupSemanticId == slots_[first].anchor.hatchGroupSemanticId)\n                    {\n                        return std::vector<std::size_t>{first, second};\n                    }\n                }\n            }\n            return std::unexpected("P-700 launcher inventory has no complete loaded paired hatch group");\n        }\n\n        std::vector<std::size_t> result;\n        result.reserve(requestedCount);\n        for (std::size_t index = 0; index < slots_.size() && result.size() < requestedCount; ++index)\n        {\n            if (slots_[index].state == P700LauncherSlotState::Loaded)\n                result.push_back(index);\n        }\n        if (result.size() != requestedCount)\n            return std::unexpected("P-700 launcher inventory does not contain enough loaded missiles for the salvo");\n        return result;\n    }\n\n    // Consumption is explicit''')

# Generic commander weapon profile can be re-armed only after its launched physical lifecycle has resolved.
replace_once(
    "Simulation/Weapons/WeaponRuntime.h",
    "} // namespace DeepRun::Weapons\n",
    '''[[nodiscard]] inline std::expected<void, std::string> ResetWeaponAfterResolvedLaunch(\n    const WeaponDefinition& definition, WeaponRuntimeState& state, const double simulationTimeSeconds)\n{\n    if (state.definitionId != definition.id)\n        return std::unexpected("weapon runtime does not match definition");\n    const auto validTime = ValidateWeaponTime(state, simulationTimeSeconds);\n    if (!validTime)\n        return std::unexpected(validTime.error());\n    if (state.phase != WeaponPhase::Launched)\n        return std::unexpected("only a resolved Launched weapon may return to Stored");\n    state.phase = WeaponPhase::Stored;\n    state.phaseEnteredTimeSeconds = simulationTimeSeconds;\n    state.lastUpdateTimeSeconds = simulationTimeSeconds;\n    state.targetTrackId.reset();\n    return {};\n}\n} // namespace DeepRun::Weapons\n''')

